import { useSelector, useDispatch } from 'react-redux';
import { locationActions, authActions } from '../store/index';
import { locations } from "../data";
import './Auth.css'

function Auth() {
    const dispatch = useDispatch();

    // const selectedLocation = useSelector(state => state.selectedLocation);

    const handleLocationChange = (event) => {
        const selectedLocation = event.target.value;
        dispatch(locationActions.updateLocation(selectedLocation));
    }

    const loginHandler = (event) => {
        event.preventDefault();

        dispatch(authActions.login());
    }

    const hidePasswordLabel = () => {
        const passwordLabel = document.querySelector('.user-box .password');
        if (passwordLabel) {
            passwordLabel.classList.add('hidden');
        }
    }

    return (
        <div class="login-box">
            <h2>Login</h2>
            <form onSubmit={loginHandler}>
                <div class="user-box">
                    <label for="locations">Location</label>
                    <select id="locations" onChange={handleLocationChange}>
                        {locations.map((location) => {
                            return (
                                <option key={`${location.value}`}>{location.value}</option>
                            )
                        })}
                    </select>
                </div>
                <div class="user-box">
                    <label id='passwo'>Password</label>
                    <input type="password" name="" required="" onClick={hidePasswordLabel} />
                </div>
                <button className='login-button'>Login</button>
            </form>
        </div>
    );
}

export default Auth;
